import { ABORT } from 'sygnal'

const PCTS = [10, 15, 20]
const money = (n, c) => c + ' ' + n.toFixed(2)

export default function Tip({ state }) {
  const tip = state.bill * state.pct / 100
  return <div className="tip">
    <p>Bill: <strong className="bill">{money(state.bill, state.currency)}</strong></p>
    <div className="pcts" role="radiogroup">
      {PCTS.map(p => <button className={p === state.pct ? 'pct on' : 'pct'} data-pct={p} aria-pressed={String(p === state.pct)}>{p}%</button>)}
    </div>
    <label>Split between <input className="people" type="number" min="1" value={state.people} /></label>
    <p className="each">Each pays {money((state.bill + tip) / state.people, state.currency)}</p>
    <button className="done">Use this</button>
  </div>
}
Tip.initialState = { bill: 0, currency: '', pct: 15, people: 1 }
Tip.intent = ({ DOM, PROPS }) => ({
  PROPS: PROPS.stream,
  PCT: DOM.select('.pct').events('click').map(e => +e.target.dataset.pct),
  PEOPLE: DOM.select('.people').events('input').map(e => parseInt(e.target.value, 10)),
  DONE: DOM.select('.done').events('click'),
})
Tip.model = {
  PROPS: (s, p) => ({ ...s, bill: p.bill, currency: p.currency }),
  PCT: (s, pct) => ({ ...s, pct }),
  PEOPLE: (s, n) => n >= 1 ? { ...s, people: n } : ABORT,
  DONE: { EVENTS: (s) => ({ type: 'ANSWER', data: { pct: s.pct, people: s.people, each: +((s.bill * (1 + s.pct / 100)) / s.people).toFixed(2) } }) },
}
